import js from "@eslint/js";
import eslintPluginPrettier from "eslint-plugin-prettier/recommended";
import globals from "globals";
import jsxA11y from "eslint-plugin-jsx-a11y";
import reactPlugin from "eslint-plugin-react";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import tseslint from "typescript-eslint";

export default tseslint.config(
  // routeTree.gen.ts is generated by the router plugin — linting it is just noise.
  { ignores: ["dist", "src/routeTree.gen.ts", "src/api/generated"] },
  {
    extends: [
      js.configs.recommended,
      ...tseslint.configs.recommendedTypeChecked,
      reactPlugin.configs.flat.recommended,
      // React 19 doesn't require React in scope — disables react-in-jsx-scope.
      reactPlugin.configs.flat["jsx-runtime"],
      // v7: rules powered by the React Compiler (purity, immutability,
      // set-state-in-effect, refs, error-boundaries…). The configs.flat variant
      // — configs["recommended-latest"] is in the old eslintrc shape
      // (plugins as an array) and flat config rejects it.
      reactHooks.configs.flat["recommended-latest"],
      jsxA11y.flatConfigs.recommended,
    ],
    files: ["**/*.{ts,tsx}"],
    languageOptions: {
      ecmaVersion: 2022,
      globals: globals.browser,
      // projectService enables type-aware rules (no-floating-promises,
      // no-misused-promises, no-unnecessary-condition).
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    plugins: { "react-refresh": reactRefresh },
    settings: { react: { version: "detect" } },
    rules: {
      "react-refresh/only-export-components": ["warn", { allowConstantExport: true }],
      "@typescript-eslint/no-unused-vars": [
        "error",
        {
          argsIgnorePattern: "^_",
          varsIgnorePattern: "^_",
          caughtErrorsIgnorePattern: "^_",
        },
      ],
      // notFound() and redirect() from TanStack Router return NotFoundError /
      // Redirect objects, not Errors — throwing them is the router's
      // documented pattern, not a bug.
      "@typescript-eslint/only-throw-error": [
        "error",
        {
          allow: [
            { from: "package", package: "@tanstack/router-core", name: "NotFoundError" },
            { from: "package", package: "@tanstack/router-core", name: "Redirect" },
          ],
        },
      ],
      // TypeScript guards props better than prop-types, which aren't used here.
      "react/prop-types": "off",
      // Copy is a message (CLAUDE.md): no sentence in the JSX, only punctuation
      // between formatted values. Attributes are not checked — a className is
      // a string too — so an aria-label is on the reviewer.
      "react/jsx-no-literals": [
        "error",
        {
          noStrings: true,
          ignoreProps: true,
          allowedStrings: [
            "·",
            "—",
            "–",
            ":",
            "(",
            ")",
            ",",
            "×",
            "/",
            "%",
            "…",
            ".",
            "−",
            "+",
            "→",
            "•",
            "|",
            "&",
            ";",
            "?",
            "!",
            "*",
            "=",
          ],
        },
      ],
      // Seven dialogs reset their form in an effect after `open` changes.
      // It's a real antipattern (React recommends remounting via `key`), but
      // rewriting them is a form refactor, not a config change — for now it's
      // visible as a warning and doesn't block the lint.
      "react-hooks/set-state-in-effect": "warn",
    },
  },
  // Vendored shadcn/ui. We don't write this code — `npx shadcn add` would
  // restore it in the same form, so fixes would evaporate anyway:
  //   only-export-components     — by convention they export cva variants next to the component
  //   heading/anchor-has-content — generic wrappers, content comes in via children
  //   no-unknown-property        — cmdk-input-wrapper is an attribute of the cmdk library
  //   purity                     — the shadcn Skeleton randomizes width via Math.random
  //   set-state-in-effect        — the carousel synchronizes with embla
  {
    files: ["src/components/ui/**"],
    rules: {
      "react/jsx-no-literals": "off",
      "react-refresh/only-export-components": "off",
      "jsx-a11y/heading-has-content": "off",
      "jsx-a11y/anchor-has-content": "off",
      "react/no-unknown-property": "off",
      "react-hooks/purity": "warn",
    },
  },
  // eslint.config.js is not part of the TS project (allowJs is false, so tsc
  // skips it) — projectService would crash on it. Type-aware rules off.
  {
    files: ["**/*.js"],
    extends: [tseslint.configs.disableTypeChecked],
    languageOptions: { globals: globals.node },
  },
  eslintPluginPrettier,
);
